(() => {
  if (globalThis.PuzzleEditorLevelShared) {
    throw new Error("PuzzleEditorLevelShared was loaded more than once.");
  }

  function transformGrid<TSource>(
    options: PuzzleEditorTransformGridIdentityOptions<TSource>,
  ): TSource[];
  function transformGrid<TSource, TResult>(
    options: PuzzleEditorTransformGridCopyOptions<TSource, TResult>,
  ): TResult[];
  function transformGrid<TSource, TResult>({
    sourceWidth,
    sourceHeight,
    targetWidth,
    targetHeight,
    mapCell,
    readCell,
    emptyCell,
    copyCell = (value) => value,
  }: PuzzleEditorTransformGridBaseOptions<TSource> & {
    copyCell?: ((value: TSource) => TSource | TResult) | undefined;
  }): Array<TSource | TResult> {
    const result: Array<TSource | TResult> = [];
    for (let y = 0; y < targetHeight; y += 1) {
      for (let x = 0; x < targetWidth; x += 1) {
        const source = mapCell(x, y, sourceWidth, sourceHeight);
        const inBounds = source
          && source.x >= 0
          && source.x < sourceWidth
          && source.y >= 0
          && source.y < sourceHeight;
        result.push(copyCell(inBounds ? readCell(source.x, source.y) : emptyCell()));
      }
    }
    return result;
  }

  function floodFill<TPosition extends object, TValue, TKey>({
    start,
    keyOf,
    inBounds,
    valueAt,
    paint,
    neighbors,
    sameValue = (left, right) => left === right,
  }: PuzzleEditorFloodFillOptions<TPosition, TValue, TKey>): number {
    if (!inBounds(start)) {
      return 0;
    }
    const targetValue = valueAt(start);
    const visited = new Set<TKey>();
    const pending: TPosition[] = [{ ...start }];
    let changed = 0;
    while (pending.length) {
      const current = pending.pop()!;
      const key = keyOf(current);
      if (visited.has(key) || !inBounds(current) || !sameValue(valueAt(current), targetValue)) {
        continue;
      }
      visited.add(key);
      if (paint(current)) {
        changed += 1;
      }
      pending.push(...neighbors(current));
    }
    return changed;
  }

  function beginPointerPaint<TSnapshot, TBrush>({
    target,
    pointerId,
    beforeSnapshot,
    brush,
  }: PuzzleEditorBeginPointerPaintOptions<TSnapshot, TBrush>): PuzzleEditorPointerPaintSession<TSnapshot, TBrush> {
    target?.setPointerCapture?.(pointerId);
    return {
      target,
      pointerId,
      beforeSnapshot,
      brush,
      lastKey: null,
      changed: false,
    };
  }

  function applyPointerPaint<TSnapshot, TBrush>(
    session: PuzzleEditorPointerPaintSession<TSnapshot, TBrush> | null | undefined,
    key: unknown,
    paint: (brush: TBrush) => PuzzleEditorPointerPaintResult,
  ): boolean {
    if (!session || key === session.lastKey) {
      return false;
    }
    session.lastKey = key;
    if (!paint(session.brush)) {
      return false;
    }
    session.changed = true;
    return true;
  }

  function finishPointerPaint<TSnapshot, TBrush>(
    session: PuzzleEditorPointerPaintSession<TSnapshot, TBrush> | null | undefined,
    pointerId: number,
    commit: (beforeSnapshot: TSnapshot) => void,
  ): boolean {
    if (!session || session.pointerId !== pointerId) {
      return false;
    }
    if (session.target?.hasPointerCapture?.(pointerId)) {
      session.target.releasePointerCapture(pointerId);
    }
    if (session.changed) {
      commit(session.beforeSnapshot);
    }
    return true;
  }

  async function startPlaytest<TPrepared>(
    lifecycle: PuzzleEditorPlaytestLifecycle<TPrepared>,
  ): Promise<boolean> {
    if (lifecycle.isActive()) {
      return false;
    }
    const prepared = await lifecycle.prepare();
    if (!prepared || !lifecycle.validate(prepared)) {
      return false;
    }
    lifecycle.beforeStart?.(prepared);
    lifecycle.setActive(true);
    lifecycle.updateControls();
    lifecycle.render();
    lifecycle.focus();
    requestAnimationFrame(lifecycle.focus);
    lifecycle.started?.(prepared);
    return true;
  }

  function stopPlaytest<TPrepared>(
    lifecycle: PuzzleEditorPlaytestLifecycle<TPrepared>,
    options: PuzzleEditorStopPlaytestOptions = {},
  ): boolean {
    if (!lifecycle.isActive() && !lifecycle.hasTransient?.()) {
      lifecycle.updateControls();
      return false;
    }
    lifecycle.setActive(false);
    lifecycle.clearTransient?.();
    lifecycle.updateControls();
    if (options.syncPreview !== false) {
      lifecycle.render();
    }
    lifecycle.stopped?.();
    return true;
  }

  function togglePlaytest<TPrepared>(lifecycle: PuzzleEditorPlaytestLifecycle<TPrepared>): void {
    if (lifecycle.isActive()) {
      stopPlaytest(lifecycle);
      return;
    }
    startPlaytest(lifecycle).catch((error: unknown) => lifecycle.failed(error));
  }

  function sendPlaytestKey({
    active,
    controller,
    event,
    send,
    unavailable,
    consume = false,
  }: PuzzleEditorSendPlaytestKeyOptions): boolean {
    if (!active) {
      return false;
    }
    if (!controller?.ready || !controller.frame?.contentWindow) {
      unavailable?.();
      return false;
    }
    const commandId = send({
      key: event.key,
      code: event.code,
      repeat: event.repeat,
      altKey: event.altKey,
      ctrlKey: event.ctrlKey,
      metaKey: event.metaKey,
      shiftKey: event.shiftKey,
      trace: false,
    }, controller.frame);
    if (consume && commandId) {
      event.preventDefault();
      event.stopPropagation();
    }
    return Boolean(commandId);
  }

  async function performSourceAction<TDocument, TResult extends PuzzleEditorSourceActionResult>({
    document,
    source,
    request,
    executeRequest,
    applyMutation,
  }: PuzzleEditorSourceActionOptions<TDocument, TResult>): Promise<TResult> {
    const operation = request?.operation;
    if (!request || (operation !== "format" && operation !== "insert" && operation !== "update")) {
      throw new Error(`Unsupported level source operation ${JSON.stringify(operation)}.`);
    }
    if (operation === "update" && !Number.isInteger(request.targetStart)) {
      throw new Error("No typed level source target is selected.");
    }
    const result = await executeRequest(source, request);
    if (operation === "format") {
      return result;
    }
    if (!document) {
      throw new Error("No puzzle source document is available.");
    }
    if (!applyMutation(document, source, result.source)) {
      const error = new Error(
        "Level source changed while the edit was being prepared; retry the edit.",
      ) as PuzzleEditorLevelSourceConflictError;
      error.code = "level-source-conflict";
      throw error;
    }
    return result;
  }

  function sourceActionErrorMessage(error: unknown, prefix: string): string {
    const typedError = error as { code?: unknown; message?: unknown } | null | undefined;
    if (
      typedError?.code === "level-source-conflict"
      && typeof typedError.message === "string"
    ) {
      return typedError.message;
    }
    const detail = typeof typedError?.message === "string" && typedError.message
      ? typedError.message
      : String(error);
    return `${prefix}: ${detail}`;
  }

  globalThis.PuzzleEditorLevelShared = Object.freeze({
    transformGrid,
    floodFill,
    beginPointerPaint,
    applyPointerPaint,
    finishPointerPaint,
    startPlaytest,
    stopPlaytest,
    togglePlaytest,
    sendPlaytestKey,
    performSourceAction,
    sourceActionErrorMessage,
  });
})();
